        ('mth11b-09-so-0140', 9, 'mth11b-09-set-016', 'Trading Outcome', 'Loss', 'Profit', 'Sale 18, cost 9', 'b', 2, 'Selling price exceeds cost price.'),
        ('mth11b-09-so-0141', 9, 'mth11b-09-set-016', 'Trading Outcome', 'Loss', 'Profit', 'Sale 15, cost 12', 'b', 2, 'Selling price exceeds cost price.'),
        ('mth11b-09-so-0142', 9, 'mth11b-09-set-016', 'Trading Outcome', 'Loss', 'Profit', 'Sale 9, cost 18', 'a', 3, 'Selling price is below cost price.')
    ) AS v (question_code, chapter_no, set_code, item_type, bucket_a, bucket_b, prompt, correct_bucket, difficulty, explanation)
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.subject, t.chapter_no, t.set_code, t.item_type, t.bucket_a, t.bucket_b, t.prompt, t.correct_bucket, t.difficulty, t.explanation) IS DISTINCT FROM (s.subject, s.chapter_no, s.set_code, s.item_type, s.bucket_a, s.bucket_b, s.prompt, s.correct_bucket, s.difficulty, s.explanation) THEN
    UPDATE SET subject = s.subject, chapter_no = s.chapter_no, set_code = s.set_code, item_type = s.item_type, bucket_a = s.bucket_a, bucket_b = s.bucket_b, prompt = s.prompt, correct_bucket = s.correct_bucket, difficulty = s.difficulty, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, subject, chapter_no, set_code, item_type, bucket_a, bucket_b, prompt, correct_bucket, difficulty, explanation) VALUES (s.question_code, s.subject, s.chapter_no, s.set_code, s.item_type, s.bucket_a, s.bucket_b, s.prompt, s.correct_bucket, s.difficulty, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.subject = 'maths2' THEN
    DELETE;
